(()=>{document.querySelectorAll(".content img").forEach(e=>{if(e.closest("a, button")||!e.getAttribute("src"))return;const n=new URL(e.getAttribute("src"),document.baseURI);if(!["http:","https:"].includes(n.protocol))return;const i=decodeURIComponent(n.pathname.split("/").pop()),s=i.match(/^(\d+)-(\d+)\./);if(!s)return;const o=e.alt.trim()||`图 ${s[1]}-${s[2]}`;e.alt=o;const t=document.createElement("a");t.href=n.href,t.className="reader-diagram",t.setAttribute("aria-label",`${o}，查看原图`),t.title="查看原图",e.before(t),t.append(e)})})()